<template>
  <aside class="context-rail">
    <section class="code-pane"><header><strong>项目代码</strong><button @click="loadFiles">刷新</button></header><input v-model="filter" placeholder="搜索文件路径" aria-label="搜索源码"><p v-if="sourceError" role="alert">{{ sourceError }}</p><SourceTree :files="files" :filter="filter" :selected="source?.path" @select="openSource"/><details v-if="source" open><summary>{{ source.path }}</summary><button @click="emit('attach', {path:source.path,text:source.text,appId})">附加到对话</button><div class="target-range"><label>起始行<input type="number" v-model.number="startLine" min="1" :max="source.line_count"></label><label>结束行<input type="number" v-model.number="endLine" :min="startLine" :max="source.line_count"></label><button :disabled="!serial || startLine < 1 || endLine < startLine || endLine > source.line_count" @click="bindTarget">用于设备任务</button></div><pre>{{ source.text }}</pre></details></section>
    <section class="device-pane"><header><strong>虚拟机 / 设备</strong><button :disabled="loading" @click="loadDevices">检测设备</button></header><select v-model="serial" aria-label="目标设备" @change="preview"><option value="">选择设备</option><option v-for="d in devices" :key="d.serial" :value="d.serial" :disabled="d.state !== 'device'">{{ d.serial }} · {{ d.state }}</option></select><p v-if="error" role="alert">{{ error }}</p><div class="device-screen"><img v-if="picture" :src="picture" alt="目标设备当前截图"><div v-else><strong>{{ serial ? '正在获取画面' : '没有连接的设备' }}</strong><p>启动 Android 模拟器后点击「检测设备」。</p></div></div><footer><span>{{ activity || '尚未获取当前 App' }}</span><button :disabled="!serial || loading" @click="preview">刷新画面</button></footer></section>
  </aside>
</template>
<script setup lang="ts">
import {ref,onMounted,watch} from 'vue'
import {authFetch} from '../utils/auth'
import SourceTree from './SourceTree.vue'
const props=defineProps<{appId:string;apiBase:string}>()
const emit=defineEmits<{attach:[value:{path:string;text:string;appId:string}];target:[value:any]}>()
const files=ref<string[]>([]),filter=ref(''),source=ref<any>(null),devices=ref<any[]>([]),serial=ref(''),picture=ref(''),activity=ref(''),error=ref(''),sourceError=ref(''),loading=ref(false)
const startLine=ref(1),endLine=ref(1)
function bindTarget(){emit('target',{app_id:props.appId,device_serial:serial.value,target:{path:source.value.path,start_line:startLine.value,end_line:endLine.value,file_sha256:source.value.file_sha256}})}
let generation=0
async function get(path:string){const r=await authFetch(`${props.apiBase}/workbench${path}`);const data=await r.json();if(!r.ok)throw new Error(data.detail || '请求失败');return data}
async function loadFiles(){const app=props.appId;sourceError.value='';try{const data=await get(`/projects/${app}/files`);if(app===props.appId)files.value=data.files}catch(e){if(app===props.appId)sourceError.value=String(e)}}
async function openSource(path:string){const app=props.appId;try{const data=await get(`/projects/${app}/source?path=${encodeURIComponent(path)}`);if(app===props.appId){source.value=data;startLine.value=1;endLine.value=1}}catch(e){sourceError.value=String(e)}}
async function loadDevices(){error.value='';try{const data=await get('/devices');devices.value=data.devices;serial.value=devices.value.find(d=>d.serial===serial.value && d.state==='device')?.serial || devices.value.find(d=>d.state==='device')?.serial || '';if(!data.available)error.value=data.reason;if(serial.value)await preview();else {picture.value='';activity.value=''}}catch(e){error.value=String(e)}}
async function preview(){const id=++generation;picture.value='';activity.value='';if(!serial.value)return;loading.value=true;error.value='';try{const data=await get(`/devices/${encodeURIComponent(serial.value)}/preview`);if(id===generation){picture.value=`data:image/png;base64,${data.screenshot}`;activity.value=data.activity || ''}}catch(e){if(id===generation)error.value=String(e)}finally{if(id===generation)loading.value=false}}
onMounted(()=>{loadFiles();loadDevices()});watch(()=>props.appId,()=>{source.value=null;files.value=[];loadFiles()})
</script>
<style scoped>
.context-rail{width:340px;flex-shrink:0;display:grid;grid-template-rows:minmax(180px,40%) minmax(280px,60%);height:100%;border-left:1px solid #dae2e8;background:#f1f5f7;color:#344b5c;font:12px 'Segoe UI','Microsoft YaHei',sans-serif}.code-pane,.device-pane{padding:16px;min-height:0;overflow:auto}.code-pane{border-bottom:1px solid #d8e1e7}.context-rail header{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.context-rail button{border:1px solid #cedae2;background:white;border-radius:5px;padding:5px 9px;color:#476376;cursor:pointer}.context-rail button:disabled{opacity:.45;cursor:default}.context-rail input,.context-rail select{width:100%;box-sizing:border-box;padding:8px;border:1px solid #cedae2;border-radius:5px;background:white;margin-bottom:8px}.context-rail pre{overflow:auto;max-height:220px;font:11px/1.6 Consolas,monospace}.context-rail summary{overflow-wrap:anywhere;cursor:pointer}.device-pane{display:flex;flex-direction:column}.device-screen{min-height:120px;flex:1;display:flex;justify-content:center;align-items:center;background:#e5ebef;border-radius:8px;overflow:hidden;text-align:center;color:#7d909e}.device-screen img{width:100%;height:100%;object-fit:contain}.device-screen p{font-size:11px;padding:0 20px}.device-pane footer{display:flex;align-items:center;gap:10px;margin-top:10px}.device-pane footer span{flex:1;overflow-wrap:anywhere;font-size:10px}.device-pane footer button{flex-shrink:0}[role=alert]{color:#a44332;font-size:11px}.code-pane :deep(.source-tree){max-height:170px}@media(max-width:1050px){.context-rail{width:280px}}@media(max-width:700px){.context-rail{width:220px}}
</style>
